import { citypesearch } from "@/api/system/ciModel";
import modelForm from "./components/modelManageComponent/modelFom";
import modelImportFom from "./components/modelManageComponent/modelImportFom";
import modelExportFom from "./components/modelManageComponent/modelExportFom";
import levelForm from "./components/modelManageComponent/levelForm";
import levelManage from "./components/modelManageComponent/levelManage";
import modelDetailForm from "./modelDetailForm";
export default {
  components: {
    modelForm: modelForm,
    modelImportFom: modelImportFom,
    modelExportFom: modelExportFom,
    levelForm: levelForm,
    levelManage: levelManage,
    modelDetailForm: modelDetailForm
  },
  data: function data() {
    return {
      showTopo: false,
      modeShowType: "card",
      searchText: '',
      modelList: [],
      pageLoading: false,
      // 弹窗相关
      showModel: false,
      showModelImport: false,
      showModelExport: false,
      showLevel: false,
      showLevelManage: false,
      showDetail: false,
      ciId: '',
      //模型id
      showType: ''
    };
  },
  mounted: function mounted() {
    this.setPageContentHeight();
    this.getModelList();
  },
  methods: {
    // 获得所有模型列表
    getModelList: function getModelList() {
      var _this = this;
      var params = arguments.length > 0 && arguments[0] !== undefined ? arguments[0] : {};
      this.pageLoading = true;
      citypesearch(params).then(function (res) {
        _this.modelList = res.Return;
        _this.pageLoading = false;
      }).catch(function (err) {
        _this.pageLoading = false;
      });
    },
    // 设置图标颜色
    getIconClass: function getIconClass(row) {
      if (row.isVirtual) {
        return 'text-grey';
      } else {
        if (!row.isAbstract) {
          return 'text_primary';
        } else {
          return 'text_default';
        }
      }
    },
    // 查看模型详情
    seeCiDetail: function seeCiDetail(row) {
      this.$refs.ciDetail.style.width = 'calc(100% - 40px)';
      this.ciId = row.id;
      // setTimeout(() => {
      //   this.showDetail = true
      // }, 500);
      this.showDetail = true;
    },
    // 返回模型管理
    backManage: function backManage() {
      var _this2 = this;
      this.$refs.ciDetail.style.width = '0px';
      this.$nextTick(function () {
        _this2.showDetail = false;
      });
    },
    // 层级保存成功回调
    saveCitype: function saveCitype() {
      this.showLevel = false;
      this.showLevelManage = false;
      this.getModelList();
    },
    // 模型保存回调
    saveCi: function saveCi() {
      this.showModel = false;
      this.getModelList();
      if (this.$refs.modelDetailForm) {
        this.$refs.modelDetailForm.getDetail(this.ciId);
      }
    },
    // 模型删除回调
    delci: function delci() {
      this.$refs.ciDetail.style.width = '0px';
      this.showDetail = false;
      this.getModelList();
    },
    // 新增模型
    addCi: function addCi() {
      this.showModel = true;
      this.showType = '新增';
    },
    // 编辑模型
    editCi: function editCi(val) {
      this.ciId = val;
      this.showModel = true;
      this.showType = '修改';
    },
    // 导入模型保存回调
    saveModel: function saveModel() {
      this.showModelImport = false;
      this.getModelList();
      if (this.$refs.modelDetailForm) {
        this.$refs.modelDetailForm.getDetail(this.ciId);
      }
    },
    // 导入模型
    importModel: function importModel() {
      this.showModelImport = true;
    },
    // 导出模型保存回调
    saveExportModel: function saveExportModel() {
      this.showModelExport = false;
      this.getModelList();
      if (this.$refs.modelDetailForm) {
        this.$refs.modelDetailForm.getDetail(this.ciId);
      }
    },
    // 导出模型
    exportModel: function exportModel() {
      this.showModelExport = true;
    },
    // 搜索模型
    searchCi: function searchCi() {
      this.getModelList({
        keyword: this.searchText
      });
    }
  }
};
